"""Generate deterministic frontend constants from canonical installation facts."""

import argparse
import sys

from package_macos_chrome import ROOT, load_installation_facts


OUTPUT = ROOT.parents[1] / "frontend/src/generated/previewsign-installation.ts"


def render() -> str:
    facts = load_installation_facts(ROOT / "installation.json")
    hosts = facts["nativeHosts"]
    return (
        "// Generated by integrations/previewsign/scripts/generate_installation_facts.py.\n"
        "// Do not edit by hand.\n"
        "export const PREVIEWSIGN_CHROME_EXTENSION_ID =\n"
        f"  '{facts['chromeExtensionId']}';\n"
        f"export const PREVIEWSIGN_MACOS_NATIVE_HOST = '{hosts['macos']}';\n"
        "export const PREVIEWSIGN_WINDOWS_NATIVE_HOST =\n"
        f"  '{hosts['windows']}';\n"
    )


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    arguments = parser.parse_args()
    expected = render()
    if arguments.check:
        if not OUTPUT.is_file() or OUTPUT.read_text(encoding="utf-8") != expected:
            print(f"stale generated installation facts: {OUTPUT}", file=sys.stderr)
            return 1
        return 0
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(expected, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
